SELECT "golem_r0"."id" AS "golem_c0", (SELECT COALESCE(json_agg("golem_cg0"."golem_payload" ORDER BY "golem_cg0"."golem_ordinal")::text, '[]') FROM (SELECT json_build_object('golem_c0', CASE WHEN "golem_cd0"."golem_c0" IS NULL THEN NULL ELSE CAST("golem_cd0"."golem_c0" AS TEXT) END, 'golem_c1', CASE WHEN "golem_cd0"."golem_c1" IS NULL THEN NULL ELSE CAST("golem_cd0"."golem_c1" AS TEXT) END) AS "golem_payload", ROW_NUMBER() OVER (ORDER BY "golem_cd0"."golem_c0" IS NOT NULL ASC, "golem_cd0"."golem_c0" ASC) AS "golem_ordinal" FROM (SELECT "golem_cr0"."id" AS "golem_c0", "golem_cr0"."title" AS "golem_c1" FROM "golem_p5_generated_social"."posts" AS "golem_cr0" WHERE (TRUE) AND ("golem_cr0"."author_id" = "golem_r0"."id")) AS "golem_cd0" ORDER BY "golem_cd0"."golem_c0" IS NOT NULL ASC, "golem_cd0"."golem_c0" ASC LIMIT $1) AS "golem_cg0") AS "golem_rel0" FROM "golem_p5_generated_social"."users" AS "golem_r0" WHERE TRUE ORDER BY "golem_r0"."id" IS NOT NULL ASC, "golem_r0"."id" ASC LIMIT $2